L3_1 = {}
L4_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_EP5_3_5_H"
L5_1 = "세상 그 무엇도 정해진 대로 흘러가는 법이란 없다.\n하지만 그런 의외성이 언제나 손해만 불러오는 것은 아니다."
