L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_EP5_4_2_H"
L7_1 = "흩어져서는 아무 것도 시작할 수 없다.\n작전의 최우선은 흩어진 멤버들을 다시 모으는 것이다."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_EP5_4_3_H"
L8_1 = "결국 어느 한 쪽이 처참하게 부서져야만 끝이 날 악연을…\n기꺼이 손꼽아 기다리는 이들도 있다."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_EP5_4_4_H"
L9_1 = "하나의 목표를 위해 멈추지 않고 달려나간다.\n돌이키기엔… 너무도 많은 것을 짊어졌으니까."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_EP5_5_1_H"
L10_1 = "델타세븐 그리고 리플레이서.\n힘과 힘이 맞부딪혔다."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_EP5_5_2_H"
L11_1 = "역사적으로 불사를 꿈꾼 이들은 온갖 만행을 저지르다 비참하게 실패했다.\n그럼에도 이러한 시도는 지금까지 이어지고 있다."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_EP5_5_3_H"
L12_1 = "싸움도, 운명도, 최후의 최후에 다다르기 전까진 그 끝을 알 수 없는 법이다."
