L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_EP5_5_4_H"
L13_1 = "홀로 남겨진 왕과,\n밝혀지는 테라사이드의 진실."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_EP5_5_5_H"
L14_1 = "무수한 좌절을 깨우쳤음에도…\n너는 한낱 희망을 택한다."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_EP5_5_6_H"
L15_1 = "연장전은 없다.\n그러니 전력을 다해서…\n이 길었던 싸움을 끝내자."
