L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP3_2_3"
L10_1 = "테러범들이 원하는 것은 관리국의 해체.\n늘 그렇듯, 수용할 수 없는 요구일 뿐이다."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP3_2_4"
