L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP3_3_1"
L12_1 = "마젤란 예언회.\n진저리 나는 그 광신도들이 또 일을 벌였다."
L10_1[1] = L11_1
