L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP3_3_3"
L14_1 = "마젤란 예언회는 신을 추종한다.\n우리에겐 여러 모로 익숙한 신들이다.\n이면세계엔 그런 것들이 아주 많으니까."
