L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SUMMER_3_EPLIOGUE"
L11_1 = "운명이란 결국 마주하게 되는 것. \n하지만 준비가 되지 않았다면 그 운명 또한 네가 지나치게 될 수많은 인연 중 하나일 뿐이지."
