L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_XMAS_1_1"
L27_1 = "앗, 결국 우려했던 일이 일어나고야 말았네."
L25_1[1] = L26_1
