L46_1 = "여인은 처음엔 만족했지만, 그것만으론 자신의 욕심을 채우지 못한다는 걸 깨닫고 더 많은 요구를 했지."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FALLEN_1_INTERLUDE_2"
