L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FALLEN_1_3"
L48_1 = "…그렇게 여인은 자신의 앞길을 가로막는 힘만 센 늑대와 마주쳤다네. \n과연, 그녀는 스스로 시련을 극복했을까?"
