L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_NEGOTIATE_DOC_1_1"
L13_1 = "1단계 측정. 코핀 컴퍼니의 사원이라면 이쯤은 금방 해내실 수 있을 거라 믿어요.\n자! 그럼 시작합니다."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_NEGOTIATE_DOC_1_2"
L14_1 = "2단계 측정. 최우수 인재가 되기 위한 길! 통과만 하시면 평가서는 잘 작성해드릴 테니 걱정 말고 다녀오세요."
L12_1[1] = L13_1
