L2_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_4_INTERLUDE_3"
L3_1 = "저 빛 너머에 있을 세상에서도 너의 벗, 너의 언니, 너의 가족이길 바라며."
