L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB001_2_2"
L45_1 = "사람은 불완전하지만, 그렇기에 자신이 그리는 목표를 향해 나아갈 수 있습니다. 돌부리에 걸려 자빠지거나 빙 돌아가야 할 때도 있지만, 그것 나름대로 쏠쏠한 재미 아닐까요?"
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB001_2_3"
