L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_INTERLUDE_3"
L5_1 = "무녀조차도 바람이 어디서부터 시작되었는지는 모른다. 그 바람이 어디로 향하는지를 알고 있을 뿐이다."
