L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_INTERLUDE_1"
L6_1 = "방향을 알고 있음에도, 결국 내딛지 못했다."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_1"
L7_1 = "하야미 가문은 연합에서 가장 뛰어난 수행원의 가문이었고 그 누구보다 신뢰받았다. 그들은 연합을 지키기 위해 모든 비밀을 알고 있어야만 했다."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_2"
L8_1 = "바람은 길을 가르쳐줄 뿐, 답을 말해주진 않아."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_3"
L9_1 = "어쩌면, 답은 처음부터 정해져있었을지도 몰라."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_4"
L10_1 = "평범하게, 정해진 답을 따르는 게 옳은 선택일지도 몰라."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_INTERLUDE_2"
L11_1 = "하지만, 내 일상을 되찾기 위한 답이 그런 거라면.\n난 그 답을 부정하겠어."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_1"
L12_1 = "연합은 무녀의 후손, 오로치를 막아줄 구원자를 필요로 했습니다.\n저는 그 기대에 부응하고자 최선을 다 했다… 그렇게 생각했어요."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_INTERLUDE_1"
L13_1 = "당주가 되는 게 싫어서 도망쳤다가, 당신을 그곳에서 우연히 만났죠.\n\n꿈에서 별똥별이 떨어졌던 장소로 갔더니, 그곳엔 네가 있었지."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_2"
