L44_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CARNIVAL_5_INTERLUDE_4"
L45_1 = "앞 못 보는 계집아이조차 올바른 신앙을 찾아 귀의하였는데, 거짓된 믿음을 부르짖는 자들에게 교단이 어찌하여 자비를 베풀겠는가? 저들에게 허락된 것은 오직 형장의 칼날뿐이로다."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
