L10_1[1] = L11_1
L11_1 = {}
L12_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_PROLOGUE"
L13_1 = "꿈을 꾼다. 벚꽃이 피는 길 위에서 우연함을 만났던, 그런 사소한 기억에 대한 꿈이다."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_INTERLUDE_1"
L14_1 = "침식병이라고 부른다. 현실을 갉아먹는 바이러스다."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_INTERLUDE_2"
L15_1 = "건물 위의 건물. \n중앙 관리지구에서 가장 면적이 넓은 빌딩으로 알려진 센트럴 클락 타워의 꼭대기에는 옛 천수각을 본딴 건물이 있다."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_INTERLUDE_3"
L16_1 = "잘 다녀오게. 모든 선택은 자네의 몫일세."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_INTERLUDE_1"
L17_1 = "영생의 대가는 가볍지 않아. 서두르게."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_INTERLUDE_2"
L18_1 = "무녀는 끝내 인간을 미워하지 못했다. 그래서 무녀의 직계 후손들 또한 대대로 인간을 지키는 길을 택했다. \n이러한 전통이 이어져 내려오며 가문 연합에는 직계 혈통을 중시하는 풍습이 생겨났다."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_INTERLUDE_3"
L19_1 = "무녀조차도 바람이 어디서부터 시작되었는지는 모른다. 그 바람이 어디로 향하는지를 알고 있을 뿐이다."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_INTERLUDE_1"
L20_1 = "방향을 알고 있음에도, 결국 내딛지 못했다."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_INTERLUDE_2"
L21_1 = "하지만, 내 일상을 되찾기 위한 답이 그런 거라면.\n난 그 답을 부정하겠어."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_INTERLUDE_1"
L22_1 = "당주가 되는 게 싫어서 도망쳤다가, 당신을 그곳에서 우연히 만났죠.\n\n꿈에서 별똥별이 떨어졌던 장소로 갔더니, 그곳엔 네가 있었지."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_EPILOGUE"
L23_1 = "내가 바라는 평범한 일상을 위해서라면, 언제라도 다시."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_EPILOGUE2"
L24_1 = "원하는 결과를 위한 인과는 혼자만의 힘으론 쌓을 수 없지."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_1"
L25_1 = "카운터가 되면 잃는 평범함을 그 당시의 사람들은 사소하다 여겼다."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_2"
L26_1 = "기록에 따르면, 침식현상과 카운터의 출현은 거의 동시에 발생했다. \n하지만 아직까지 둘 중 무엇도 단순한 등급 외의 세부적인 분류 항목은 없다."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_3"
L27_1 = "주거구역에는 풀숲이 우거진 비개발 구획이 있다. 도시전설 외의 진짜 실체를 아는 사람은 드물다."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_1"
L28_1 = "미나토, 이 활이 널 지켜줄 거다. 네 자신을, 그리고 네가 바라는 것을. \n그러니 언제나 연습하며 정진하거라."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_2"
L29_1 = "하야미 가문이 봉인을 앞둔 선대 당주를 살해하며, 모든 인과가 꼬였다.\n그 사건이 아니었다면 3년 전의 실패도 일어나지 않았을 거라고, 연합은 그렇게 믿고 있다."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_3"
L30_1 = "인간은 짧은 생에서 많은 되풀이를 한다. \n좋은 일도, 나쁜 일도, 겪어보지 못하면 모르는 경험이다."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_1"
L31_1 = "하야미 가문은 연합에서 가장 뛰어난 수행원의 가문이었고 그 누구보다 신뢰받았다. 그들은 연합을 지키기 위해 모든 비밀을 알고 있어야만 했다."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_2"
L32_1 = "바람은 길을 가르쳐줄 뿐, 답을 말해주진 않아."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_3"
L33_1 = "어쩌면, 답은 처음부터 정해져있었을지도 몰라."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_4"
L34_1 = "평범하게, 정해진 답을 따르는 게 옳은 선택일지도 몰라."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_1"
L35_1 = "연합은 무녀의 후손, 오로치를 막아줄 구원자를 필요로 했습니다.\n저는 그 기대에 부응하고자 최선을 다 했다… 그렇게 생각했어요."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_2"
L36_1 = "내가 구하려는 건 무녀의 후손이나 구원자가 아니야."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_3"
L37_1 = "난 너를 구하겠어."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_1_HM"
L38_1 = "수호신은 인간의 독에 스러진 여인을 삼키고 역신이 되었다네."
L36_1[1] = L37_1
L36_1[2] = L38_1
