L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_CC_NORMAL_JUNIOR_POLEARM_2"
L23_1 = "아카데미 임원들과 함께 활동하던 초등부 인원으로부터 미세한 CRF변화가 관측되었습니다."
L21_1[1] = L22_1
