L22_1 = {}
L23_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_CC_NORMAL_JUNIOR_POLEARM_3"
L24_1 = "누구나 처음으로 꿈을 가졌을 때가 가장 빛나기 마련이죠. 그리고 그 꿈을 이뤘을 때, 다시 한 번 빛날 겁니다."
