L7_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_CHALLENGE_SOF_1_2"
L8_1 = "메이슨 사무소 설명_2"
L6_1[1] = L7_1
L6_1[2] = L8_1
