L29_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_CHALLENGE_HB_1_1"
L30_1 = "미… 미하~\n오늘은 미야와 팬 여러분만의 데이… 데이트으… 방송이랍니다!\n휴. 떨려…."
L28_1[1] = L29_1
L28_1[2] = L30_1
