L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB004_PROLOGUE1"
L20_1 = "미궁도시 오라리오─ 통칭 던전이라 불리는 장대한 지하미궁을 보유한 거대 도시. 미지라는 이름의 흥분, 찬란한 영예, 그리고 예쁜 여자아이들과의 로맨스. 이곳에는 모든 꿈과 욕망이 숨죽어 있다."
