L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB004_PROLOGUE2"
L21_1 = "악명높은 블랙기업 코핀 컴퍼니에도 불문율이 있다.\n휴일에는 건들지 말 것.\n딱히 지켜진 적은 없다."
