L26_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB004_INTERLUDE5"
L27_1 = "여기, 예쁜 여자아이들과의 하렘을 추구했던 한 기계의 꿈이 바스러지니."
L25_1[1] = L26_1
L25_1[2] = L27_1
