L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_INTERLUDE2"
L4_1 = "누구에게나 태어난 고향이 있다.\n그곳에 되돌아 갈 수 있느냐는 다른 문제겠지만."
