L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_INTERLUDE9"
L19_1 = "미네르바의 부엉이는 황혼이 저물어야 그 날개를 편다."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_3_3"
L20_1 = "오랜 방황 끝에 간신히 도달한 길이 사실은, 막다른 길이었을지도 모른다."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
