L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_ACADEMY_INTERLUDE7"
L36_1 = "남들보다 우월해지고 싶다는 원초적인 욕망은 굳이 학교가 아니더라도, 도시가 가르쳐왔으니까요."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_ACADEMY_3_1"
L37_1 = "우릴 보호해주는 관리국이 말하고 있잖아요. 너희는 별로 쓸모가 없을 거라고."
L35_1[1] = L36_1
