L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_ACADEMY_3_2"
L39_1 = "남의 믿음 저버리는 것 따위, 꿈을 위해서라면 아무래도 좋다고 생각했어."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_ACADEMY_3_3"
L40_1 = "그런데… 이런 피로 더럽혀진 길도, 꿈을 위해 걸었다고 말할 수 있는 걸까?"
L38_1[1] = L39_1
L38_1[2] = L40_1
