L2_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_3_1"
L3_1 = "셰퍼드… 그 아이는 어떻게 이런 곳에서 살아남은 걸까?"
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE9"
L4_1 = "침식증후군 탓인지, 약 기운 때문인지… 종종 환각을 볼 때가 있어. 그 환각은 대부분 날 미친 사람처럼 보이게 하지만, 가끔은 도움을 주기도 하더라고."
