L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE10"
L5_1 = "죽으려고 들어온 게 아니니까. 살아나가려면 뭐라도 해야겠지."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE11"
L6_1 = "이면세계의 침식체는 개체 별로 정말 다양한 특징이 있어. 하지만 차원계면을 넘나드는 건 그림자만의 특징이지."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE12"
L7_1 = "그래. 살아남으려면 뭐든 해야해. 하지만 궁지에 몰려 선택을 해야 한다면… 적어도 인간다움을 저버리고 싶진 않아."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_4_1"
L8_1 = "그때는 몰랐지. 그 아이가 그곳에 갇혀 있던 시간이 우리의 목숨을 살리게 될 줄은…"
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE13"
L9_1 = "떠난 사람을 향한 증오, 후회, 허탈감. 여러 감정이 치밀었지만 그 사이엔 작은 안도감도 있었어."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE14"
L10_1 = "난 그 아이가 더 이상 고통받지 않았으면 했어. 하지만 차마 결정을 내리지 못하고 있었지."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE15"
L11_1 = "아이가 괴로워하는 동안에도, 난 치료약을 만들기 위해 연구에 매진했어. 시간이 얼마나 남든, 그 아이 곁을 지켜줬어야 했는데… 바보 같이 겁이 났나봐."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE16"
L12_1 = "아이가 사라진 건… 원래대로라면 그 아이가 가장 행복했어야 할 날이었어."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE17"
L13_1 = "그때 내가 무슨 생일선물로 뭘 준비했었는지… 이젠 잘 기억이 나지 않아. 침식증후군 때문인 걸까? 어쩌면 그날을 떠올리고 싶지 않았던 걸지도 모르지."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE18"
L14_1 = "그래… 그 아이가 가장 좋아하는 건 자장가였어. 곁에서 불러주면 항상 웃는 표정으로 잠들곤 했거든."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE19"
L15_1 = "하지만 이젠 알 것 같아. 그 아이는 자장가를 좋아했던 게 아니라, 우리가 곁에서 노래를 불러주길 바랐던 거야."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_5_1"
L16_1 = "미안해. 너무 당연한 사실을… 너무 늦게 알아버려서."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE20"
L17_1 = "이게 최선이 아니라는 건 알아. 하지만 너를 또다시 잃을 수는 없어."
