L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_YAKSHA_3_3"
L45_1 = "오직 그것만이 너를 위해 짊어질 수 있는 나의 책임.\n오직 그것만이 너를 살리기 위한 나의 선택.\n오직 그것만이 너의 죽음이 그림자로 얼룩지지 않길 바라는 나의 결의."
L43_1[1] = L44_1
L43_1[2] = L45_1
