L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_WINTERVACATION_INTERLUDE4"
L38_1 = "관리국은 침식으로부터 인류를 보호할 뿐, 국가 자격을 대변하지 않는다. 하지만 협조적인 시민들이 안전할 수 있도록 최소한의 수칙을 정해두고 있다.\n불법 거주자들에게 엄격한 점이 그렇다."
