L4_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_MOONLIGHT_1_1"
L5_1 = "퇴마란, 간단하게 말해서 사람들 몰래 침식 쐐기를 파괴하는 행위이다."
