L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_MOONLIGHT_INTERLUDE6"
L8_1 = "예민해진 후각은 때론, 남들이 맡지 못하는 냄새를 맡는다.\n아스팔트 냄새, 피 냄새, 침식파 냄새, 그리고 과거의 냄새까지."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_MOONLIGHT_2_1"
L9_1 = "숙원이란 거대한 아귀와도 같다.\n자신을 향해 다가오는 모든 것을 집어삼켜 버리니까."
