L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_MOONLIGHT_3_1"
L14_1 = "침식 현상은 인간의 본능에 각인된 감정을 투영한다.\n이를 이용해 어떤 이들은 침식파를 이용하여 원하는 형태를 유도해 자신만의 공간을 만들었다."
L12_1[1] = L13_1
