L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_PRIDE_INTERLUDE14"
L4_1 = "별의 무구란 인도자가 제시한 하나의 가능성에 불과하다.\n별의 인도에 따라 자신의 갈 길을 찾는 것이 별의 인도라면, 그 무구 역시 동일하지 않겠는가.\n중요한 것은 정해진 형태에 얽매이지 않는 것이다."
