L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_PRIDE_INTERLUDE15"
L5_1 = "단상에 선 여인을 바라보았다.\n그 모습은 분명, 자신이 바라던 이상이었다."
