L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_2_INTERLUDE6"
L4_1 = "제멋대로 씨앗을 뿌리던 나에게 멋대로 다가온 소녀는 어느새 가능성을 품은 꽃봉오리가 되었다."
