L34_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_INTERLUDE4"
L35_1 = "그녀가 가진 재능은 인간답지 않았기에 괴물이라 불렸다.\n그녀가 가진 재능은 인간답지 않았기에 요정이라 불렸다.\n사람들이 그녀를 뭐라 생각하든, 그녀의 바람은 늘 같았다.\n더 나은 세상을 위해서."
L33_1[1] = L34_1
L33_1[2] = L35_1
